import re

def smollm(input_string):
    """
    Smollm a string, and returns a dictionary of the output.
    """
    pattern = r"^(?P<name>[a-zA-Z0-9_]+)\s*(?P<description>[a-zA-Z0-9_]+)\s*$"
    match = re.match(pattern, input_string)
    if match:
        return {
            "name": match.group("name"),
            "description": match.group("description"),
        }
    else:
        return {}
